__NUXT_JSONP__("/de/going-to-college", (function(a,b,c,d){return {data:[{details:{slug:d,pageTitle:"MLI University and College Pathways Partners | Mentor Language Institute",pageDescription:"Students who finish Mentor Language Institute's advanced-level classes can apply to these Bachelor's degree and Master's degree programs without TOEFL or IELTS upon completion of the university's approved language exam and meeting their academic qualifications.",title:"MLI University and College Pathways Partners",university:{title:"University Agreements",description:"Students who finish Mentor Language Institute's advanced-level classes can apply to these Bachelor's degree and Master's degree programs without TOEFL or IELTS upon completion of the university's approved language exam and meeting their academic qualifications.'",lists:[{image:"\u002Fimages\u002Fgoing-to-college\u002Fyum.png",link:"https:\u002F\u002Fwww.adelphi.edu\u002F",title:"Adelphi University",address:"Long Island, New York",subtitle:c,description:"Adelphi fosters in its students a passion for knowledge, an understanding and questioning of cultural values and a view of themselves as independent, lifelong learners and contributors to knowledge and service in an ever-changing world."},{image:"\u002Fimages\u002Fgoing-to-college\u002Finternational-accelerator.png",link:"https:\u002F\u002Fwww.american.edu\u002F",title:"American University",address:"Washington, D.C.",subtitle:c,description:"AU offers a broad and flexible choice of majors and minors. Students may double major, construct their own interdisciplinary major, or have their major in one school and a minor in another. AU encourages students to transcend the boundaries of academic disciplines."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fauburn-university.png",link:"https:\u002F\u002Fwww.auburn.edu\u002F",title:"Auburn University",address:"Auburn, Alabama",subtitle:c,description:"Auburn University is committed to preparing our students for today's global economy. The Office of International Programs site provides information on the international presence of Auburn University such as the Office of International Education, which provides International Student\u002FScholar immigration advising, study abroad options and more, information on initiatives sponsored by the academic units, and international admissions for undergraduate and graduate students."},{image:"\u002Fimages\u002Fgoing-to-college\u002Ffloria-international-university.png",link:"https:\u002F\u002Fwww.fiu.edu\u002F",title:"Floria International University",address:"Miami, Florida",subtitle:a,description:"Florida International welcomes students to a diverse, friendly community where industry connections and internship opportunities will help launch their career in a global marketplace. At FIU they’ll receive an outstanding education in an entrepreneurial city."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flouisiana-state-university.png",link:"https:\u002F\u002Fwww.lsu.edu\u002F",title:"Louisiana State University",address:"Baton Rougue, Louisiana",subtitle:a,description:"Earning an LSU degree is an investment in a student’s future. LSU offers an exceptional education and opportunities to have a fulfilling but affordable college experience."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-kansas.png",link:"https:\u002F\u002Fwww.ku.edu\u002F",title:"The University of Kansas",address:"Lawrence, Kansas",subtitle:a,description:"A world of advanced scholarship, invention and discovery, KU provides an education that produces global leaders, business giants and visionaries in many fields, and an undergraduate student experience that will change their life."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-central-florida.png",link:"https:\u002F\u002Fwww.ucf.edu\u002F",title:"University of Central Florida",address:"Orlando, Florida",subtitle:a,description:"Students have big dreams. Maybe they want to travel the world, run their own business or hold patents that help save lives. The University of Central Florida will help them get there."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-the-pacific.png",link:"https:\u002F\u002Fwww.pacific.edu\u002F",title:"University of the Pacific",address:"Stockton, California",subtitle:a,description:"University of the Pacific is located on a beautiful campus 1.5 hours from San Francisco. In addition to liberal arts, the University has schools of education, engineering and business, and graduate schools in dentistry, law, pharmacy and health sciences. The oldest chartered university in California, Pacific was first in the state to admit women."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-south-carolina.png",link:"https:\u002F\u002Fwww.sc.edu\u002F",title:"University of South Carolina",address:"Columbia, South Carolina",subtitle:a,description:"The University of South Carolina is where students prepare to be tomorrow’s creative problem solvers who will lead future generations to a healthier, smarter and more vibrant way of life."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-illinois.png",link:"https:\u002F\u002Fwww.uic.edu\u002F",title:"University of Illinois at Chicago",address:"Chicago, Illinois",subtitle:a,description:"University of Illinois at Chicago (UIC) broadens educational opportunities for students from across the globe through an emphasis on diversity and providing students with an ethnically and culturally rich learning environment."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-utah.png",link:"https:\u002F\u002Fwww.utah.edu\u002F",title:"The University of Utah",address:"Salt Lake City, Utah",subtitle:a,description:"The University of Utah is one of the best in the nation at creating startup companies based on student and faculty research. This is indicative of the innovative and industrious thinking found across campus and in classrooms."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-dayton.png",link:"https:\u002F\u002Fwww.udayton.edu\u002F",title:"University of Dayton",address:"Dayton, Ohio",subtitle:a,description:"The University of Dayton is a top-tier national Catholic research university and the largest private university in Ohio. Founded in 1850 by the Society of Mary (Marianists), the University is characterized by the Marianist educational philosophy of learning in community, welcoming all, serving others, intellectual curiosity and academic rigor to foster servant-leaders who connect learning with leadership and service."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fumass-amherst.png",link:"https:\u002F\u002Fwww.umass.edu\u002F",title:"UMass Amherst",address:"Amherst, Massachusetts",subtitle:a,description:"UMass Amherst is one of the major public research universities in America. Nestled in idyllic Amherst, Massachusetts, the campus is consistently ranked among the top public research universities in the nation, and offers a rich cultural environment in a rural setting close to major urban centers."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-cincinnati.png",link:"https:\u002F\u002Fwww.uc.edu\u002F",title:"University of Cincinnati",address:"Cincinnati, Ohio",subtitle:a,description:"With Cincinnati home to ten fortune 500 companies, the University of Cincinnati is a center for future achievers, leaders, and those with a thirst for knowledge. Ranked #135 in National Universities according to U.S. News & World Report, it boasts school spirit with a quarter-million bearcat alumni worldwide."}]},campus:{title:"College Agreements",description:"MLI has special agreements, or Mutual Recognition Programs (MRP), with many Los Angeles area colleges. These MRP agreements allow students to transfer without a TOEFL® score, and some also allow concurrent enrollment, which means MLI students can take part-time credit classes while still enrolled at MLI. Students must successfully complete MLI's high-intermediate program to be eligible.",lists:[{image:"\u002Fimages\u002Fgoing-to-college\u002Fsanta-monica-college.png",link:"https:\u002F\u002Fwww.smc.edu\u002F",title:"Santa Monica College",address:"Santa Monica, California",subtitle:a,description:"Santa Monica College has transferred more students to the University of California campuses than any other college in the country—for 27  years straight. SMC also tops in transfers to UCLA, USC and Loyola Marymount University, and is the top feeder west of the Mississippi to the Ivy League Columbia University."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fglendale-community-college.png",link:"https:\u002F\u002Fwww.glendale.edu\u002F",title:"Glendale Community College",address:"Glendale, California",subtitle:a,description:"Glendale Community College is a dynamic institution with more than 25,000 students. They are enrolled in college-credit at the Verdugo Campus, continuing education at the Garfield Campus, community services classes held throughout the community, and the Professional Development Center (PDC) located in Montrose. The college serves an ethnically diverse student body with no single group forming a majority."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fpasadena-city-college.png",link:"https:\u002F\u002Fpasadena.edu\u002F",title:"Pasadena City College",address:"Pasadena, California",subtitle:a,description:"Pasadena City College provides the San Gabriel Valley with a high quality, innovative and dynamic learning environment that inspires student success. Each semester we offer academic programs that encompass degrees, transfer programs, and certificates, to 30,250+ students. We are new students and returning students. We are local, international, and online. We span many cultures — LGBT, multicultural, veterans, and everyone else in between."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fcypress-college.png",link:"https:\u002F\u002Fwww.cypresscollege.edu\u002F",title:"Cypress College",address:"Cypress, California",subtitle:a,description:"Cypress College emphasizes education for the individual student. Excellence of instruction and individualized learning laboratories enhance the possibility for students to achieve their highest potential. In addition, a staff of tutors and full-time counselors provides instructional support and extensive guidance information to aid students in their choice of programs and classes. For the student who plans to complete a bachelors degree, the college provides a smooth transition from high school to colleges and universities."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fwest-los-angeles-college.png",link:"http:\u002F\u002Fwww.wlac.edu\u002F",title:"West Los Angeles College",address:"Culver City, California",subtitle:a,description:"West Los Angeles College is an accredited California Community College offering paths to university transfer, career education and courses for personal or professional growth. It occupies 70 park-like acres overlooking Culver City, Marina Del Rey and Greater West Los Angeles. On a clear day, from the highest points on campus, you can see the Pacific Ocean. With an active student population of nearly 12,000 regular and extension students, our 110 full-time faculty, more than 300 hourly faculty and 112 classified staff create an educational environment unique in Southern California."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fel-camino-college.png",link:"https:\u002F\u002Fwww.elcamino.edu\u002F",title:"El Camino College",address:"Torrance, California",subtitle:a,description:"Did you know El Camino College offers many outstanding features?\u003Cul\u003E\u003Cli\u003EA leading Southern California transfer institution\u003C\u002Fli\u003E\u003Cli\u003EConveniently located and ample parking\u003C\u002Fli\u003E\u003Cli\u003EOutstanding community education programs\u003C\u002Fli\u003E\u003Cli\u003EOver 80 highly acclaimed career programs\u003C\u002Fli\u003E\u003C\u002Ful\u003E"},{image:"\u002Fimages\u002Fgoing-to-college\u002Fpierce-college.png",link:"http:\u002F\u002Fwww.piercecollege.edu\u002F",title:"Pierce College",address:b,subtitle:a,description:"Pierce College is a flourishing two-year public institution in Southern California providing opportunities for transfer education, occupational training, and life-long learning. Pierce combines academic excellence with a friendly and helpful faculty and staff. It has a solid reputation for being a student-friendly institution, offering students high-quality and challenging education that will prepare them for university or vocational work. Pierce students benefit from smaller class sizes and lower tuition than a four-year university."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flatcc.png",link:"http:\u002F\u002Fwww.lattc.edu\u002F",title:"LATCC - Traning. Transfer. Tradition. Trade Tech.",address:b,subtitle:a,description:"Mission Statement: Los Angeles Trade Technical College advances communities through pathways to academic, career, and transfer success that empower students to achieve career technical certificates, associate degrees, transfer, and employment. Our Vision: Los Angeles Trade Technical College will be a premier community college recognized regionally and nationally for transforming students’ lives and their communities."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flos-angeles-harbor-college.png",link:"https:\u002F\u002Fwww.lahc.edu\u002F",title:"Los Angeles Harbor College",address:b,subtitle:a,description:"Los Angeles Harbor College promotes access and student success through associate and transfer degrees, certificates, economic and workforce development, and basic skills instruction. Our educational  programs and support  services meet the needs of diverse communities as measured by campus institutional learning outcomes."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fnew-york-film-academy.png",link:"https:\u002F\u002Fwww.nyfa.edu\u002F",title:"New York Film Academy",address:"Battery Place, New York",subtitle:a,description:"Over the past 25 years, the New York Film Academy (NYFA) has built a reputation as one of the premier visual and performing arts schools in the world. Our innovative programs are designed for a new generation of storytellers – for artists who share a passion for visual and performing arts, across a wide array of media and want to learn by doing. With an unrivaled approach to hands-on, interactive learning, students find themselves completely immersed in their course of study from day one. Classes are taught by award-winning industry professionals, in a real-world environment with state-of-the-art facilities and equipment."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flacc-city-college.png",link:"https:\u002Fwww.lacitycollege.edu",title:"Los Angeles City College",address:b,subtitle:a,description:"LACC provides a dynamic and innovative learning environment offering more than 100 vocational and professional programs including degrees, transfer programs, and certificates to more than 18,000 students. In 2019, LACC will celebrate its 90th anniversary.\u003Cbr\u003EUnder the LA College Promise, we offer one year of free enrollment to all full-time students graduating from LAUSD high schools and charter schools. We also offer music majors tuition free attendance, private lessons and financial aid thanks to a gift from The Herb Alpert Foundation. Additionally, our students benefit from a wide variety of financial aid options."}]},contactUs:{title:"Need More Information? Contact us",description:"Contact us by phone, email or via our social media channels.",btnText:"Contact Us"},dir:"\u002Fgoing-to-college",path:"\u002Fgoing-to-college\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:29.392Z",updatedAt:"2025-05-26T12:06:27.771Z"},lang:d}],fetch:{},mutations:void 0}}("","Los Angeles, California","(Graduate Programs Available)","de")));